package com.shazwan.idash3;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.media.session.*;import java.util.*;
public class BitChordChecks extends Instrumentation {
 LauncherActivity a;int n;android.content.SharedPreferences p;Map<String,?> saved;
 void check(boolean b,String s){if(!b)throw new AssertionError(s);n++;}
 void ui(Runnable r){Throwable[] err={null};runOnMainSync(()->{try{r.run();}catch(Throwable e){err[0]=e;}});if(err[0]!=null)throw new AssertionError(err[0]);}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle out=new Bundle();int code=Activity.RESULT_CANCELED;try{p=getTargetContext().getSharedPreferences("idash",0);saved=new HashMap<>(p.getAll());p.edit().putBoolean("motion",false).putBoolean("dashboard_location",false).putInt("dashboard_panel",0).apply();ActivityMonitor mon=addMonitor(LauncherActivity.class.getName(),null,false);getTargetContext().startActivity(new Intent(getTargetContext(),LauncherActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));a=(LauncherActivity)mon.waitForActivityWithTimeout(30000);removeMonitor(mon);check(a!=null,"started");java.util.concurrent.CountDownLatch wait=new java.util.concurrent.CountDownLatch(1);a.worker.execute(()->a.main.post(wait::countDown));check(wait.await(45,java.util.concurrent.TimeUnit.SECONDS),"catalog ready");
 ui(()->{a.page="drive";a.render();DriveDashboard d=a.driveDashboard;d.setMode(4);BitChordPanel panel=d.bitChord;check(panel!=null&&d.map==null&&d.web==null&&d.fm==null,"native BitChord releases other sources");check(panel.media.bitChordOnly&&panel.media.active,"filtered bridge active");check(d.modeButtons[4].isSelected(),"BitChord selected");d.modeButtons[4].performClick();check(panel==d.bitChord,"same source preserves panel");
 MediaSession session=new MediaSession(a,"other-app-fixture");try{MediaController unrelated=session.getController();panel.media.select(Collections.singletonList(unrelated));check(panel.media.controller==null,"unrelated app cannot be controlled");ControlMedia normal=new ControlMedia(a,null);normal.active=true;normal.select(Collections.singletonList(unrelated));MediaController original=normal.controller;check(original!=null,"general media retains existing app selection");normal.bind(new MediaController(a,session.getSessionToken()));check(normal.controller==original,"same session token avoids duplicate callback binding");normal.pause();}finally{session.release();}
 for(int[] size:new int[][]{{1024,600},{800,480}}){d.measure(View.MeasureSpec.makeMeasureSpec(size[0],View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(size[1],View.MeasureSpec.EXACTLY));d.layout(0,0,size[0],size[1]);android.view.ViewGroup rail=(android.view.ViewGroup)d.getChildAt(0);for(int i=1;i<rail.getChildCount();i++){View v=rail.getChildAt(i);if(v.getHeight()>0)check(v.getBottom()<=rail.getHeight(),"rail fits at "+size[1]);}check(panel.getWidth()>250&&panel.getHeight()>250,"usable native panel");}
 d.pause();check(!panel.media.active&&!panel.media.listening,"pause releases subscriptions");d.resume();check(panel.media.active,"resume restores subscriptions");a.showApps();a.closeApps();check(a.driveDashboard.mode==4&&a.driveDashboard.bitChord!=null,"Apps Done returns to BitChord");check(panel.closed&&!panel.media.active,"old panel closed");a.onBackPressed();check(a.driveDashboard.mode==0,"Back returns to map");if(a.driveDashboard.map!=null)a.driveDashboard.map.setUseDataConnection(false);
 });out.putString("stream","PASS: "+n+" BitChord native integration assertions\n");code=Activity.RESULT_OK;
 }catch(Throwable t){out.putString("stream","FAIL after "+n+": "+t+"\n");}finally{if(a!=null)ui(a::finish);if(p!=null&&saved!=null)AppearanceChecks.restore(p,saved);}finish(code,out);}
}
